<script setup>
import { ref, computed, watch } from 'vue'
import { LayoutDashboard, Package, ShoppingCart, ClipboardList, Plus, Search, Pencil, Trash2, Minus, Check, Menu, X, Wrench, ArrowUpRight, CircleAlert, Download, RotateCcw, ReceiptText, Boxes } from 'lucide-vue-next'
import StatCard from './components/StatCard.vue'
import ProductForm from './components/ProductForm.vue'

const KEY='ferrecontrol_jorgedaniel_v1'
const categories=['Herramientas','Electricidad','Plomería','Pinturas','Construcción','Accesorios']
const sampleProducts=[
{id:1,sku:'FER-001',name:'Taladro percutor 650W',category:'Herramientas',price:449.00,stock:14,minStock:5},
{id:2,sku:'FER-002',name:'Martillo de uña 16 oz',category:'Herramientas',price:65.00,stock:32,minStock:8},
{id:3,sku:'FER-003',name:'Cemento gris 42.5 kg',category:'Construcción',price:88.50,stock:45,minStock:12},
{id:4,sku:'FER-004',name:'Tubo PVC 1/2 pulgada',category:'Plomería',price:24.00,stock:8,minStock:10},
{id:5,sku:'FER-005',name:'Pintura látex blanca 1 galón',category:'Pinturas',price:189.00,stock:18,minStock:6},
{id:6,sku:'FER-006',name:'Cable eléctrico THHN 12 AWG (m)',category:'Electricidad',price:6.75,stock:74,minStock:20},
{id:7,sku:'FER-007',name:'Juego de destornilladores',category:'Herramientas',price:125.00,stock:5,minStock:6},
{id:8,sku:'FER-008',name:'Interruptor sencillo',category:'Electricidad',price:18.00,stock:26,minStock:8},
{id:9,sku:'FER-009',name:'Codo PVC 90° 1/2 pulgada',category:'Plomería',price:3.50,stock:60,minStock:15},
{id:10,sku:'FER-010',name:'Cinta métrica de 5 metros',category:'Accesorios',price:39.00,stock:20,minStock:5}
]
function load(){try{const stored=JSON.parse(localStorage.getItem(KEY));if(stored && Array.isArray(stored.products) && Array.isArray(stored.sales))return stored}catch(e){}return {products:sampleProducts.map(p=>({...p})),sales:[]} }
const data=ref(load())
watch(data, value=>localStorage.setItem(KEY,JSON.stringify(value)),{deep:true})
const page=ref('dashboard'), search=ref(''), category=ref('Todas'), formOpen=ref(false), editing=ref(null), cart=ref([]), notice=ref(''), mobileMenu=ref(false)
const money=n=>'Q '+Number(n||0).toLocaleString('es-GT',{minimumFractionDigits:2,maximumFractionDigits:2})
const dateTime=d=>new Date(d).toLocaleString('es-GT',{dateStyle:'medium',timeStyle:'short'})
const productCount=computed(()=>data.value.products.length)
const stockTotal=computed(()=>data.value.products.reduce((sum,p)=>sum+p.stock,0))
const alerts=computed(()=>data.value.products.filter(p=>p.stock<=p.minStock))
const totalRevenue=computed(()=>data.value.sales.reduce((sum,s)=>sum+s.total,0))
const filtered=computed(()=>data.value.products.filter(p=>(category.value==='Todas'||p.category===category.value)&&`${p.name} ${p.sku} ${p.category}`.toLowerCase().includes(search.value.toLowerCase())))
const bestSellers=computed(()=>{ const counts={}; data.value.sales.forEach(s=>s.items.forEach(i=>{counts[i.id]=(counts[i.id]||0)+i.quantity}));return data.value.products.map(p=>({...p,sold:counts[p.id]||0})).sort((a,b)=>b.sold-a.sold).slice(0,5) })
const cartTotal=computed(()=>cart.value.reduce((sum,i)=>sum+i.price*i.quantity,0))
const cartQuantity=computed(()=>cart.value.reduce((sum,i)=>sum+i.quantity,0))
const availableToAdd=p=>p.stock-(cart.value.find(i=>i.id===p.id)?.quantity||0)
function navigate(to){page.value=to;mobileMenu.value=false;search.value='';category.value='Todas'}
function notify(message){notice.value=message;setTimeout(()=>{if(notice.value===message)notice.value=''},3300)}
function openForm(p=null){editing.value=p?{...p}:null;formOpen.value=true}
function saveProduct(p){const match=data.value.products.some(existing=>existing.sku.toLowerCase()===p.sku.toLowerCase()&&existing.id!==editing.value?.id);if(match)return alert('Este código SKU ya existe.');if(editing.value){data.value.products=data.value.products.map(x=>x.id===editing.value.id?{...p,id:x.id}:x);notify('Producto actualizado correctamente')}else{data.value.products.push({...p,id:Date.now()});notify('Producto registrado correctamente')}formOpen.value=false}
function removeProduct(p){if(!confirm(`¿Eliminar “${p.name}” del inventario?`))return;data.value.products=data.value.products.filter(x=>x.id!==p.id);cart.value=cart.value.filter(x=>x.id!==p.id);notify('Producto eliminado')}
function addCart(p){if(availableToAdd(p)<=0)return notify('No hay existencias suficientes');const item=cart.value.find(i=>i.id===p.id);if(item)item.quantity++;else cart.value.push({id:p.id,name:p.name,price:p.price,quantity:1});notify('Agregado al carrito')}
function adjust(id,step){const line=cart.value.find(i=>i.id===id);if(!line)return;const product=data.value.products.find(p=>p.id===id);if(step>0 && (!product || line.quantity>=product.stock))return notify('No hay más existencias');line.quantity+=step;if(line.quantity<=0)cart.value=cart.value.filter(i=>i.id!==id)}
function checkout(){if(!cart.value.length)return;for(const item of cart.value){const p=data.value.products.find(p=>p.id===item.id);if(!p||p.stock<item.quantity)return notify('Inventario insuficiente; revisa el carrito')}const sale={id:`V-${String(Date.now()).slice(-8)}`,date:new Date().toISOString(),items:cart.value.map(x=>({...x})),total:Number(cartTotal.value.toFixed(2))};data.value.products=data.value.products.map(p=>{const found=cart.value.find(c=>c.id===p.id);return found?{...p,stock:p.stock-found.quantity}:p});data.value.sales.unshift(sale);cart.value=[];notify('¡Venta registrada con éxito!');page.value='history'}
function exportCsv(){const rows=[['Código','Fecha','Artículos','Total (Q)'],...data.value.sales.map(s=>[s.id,dateTime(s.date),s.items.map(i=>`${i.name} x${i.quantity}`).join(' / '),s.total.toFixed(2)])];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download='ventas_ferrecontrol.csv';link.click();URL.revokeObjectURL(link.href)}
function restoreDemo(){if(!confirm('¿Restablecer los productos de ejemplo y eliminar las ventas registradas?'))return;data.value={products:sampleProducts.map(p=>({...p})),sales:[]};cart.value=[];notify('Datos de demostración restaurados')}
const menu=[{id:'dashboard',label:'Resumen',icon:LayoutDashboard},{id:'products',label:'Productos',icon:Package},{id:'sales',label:'Nueva venta',icon:ShoppingCart},{id:'history',label:'Historial de ventas',icon:ClipboardList}]
</script>

<template>
<div class="app-shell">
  <aside class="sidebar" :class="{'show':mobileMenu}">
    <div class="logo"><div class="logo-symbol"><Wrench :size="22"/></div><div><strong>FERRE<span>CONTROL</span></strong><small>Gestión inteligente</small></div></div>
    <div class="side-caption">MENÚ PRINCIPAL</div>
    <nav class="navigation"><button v-for="item in menu" :key="item.id" :class="['nav-item',{active:page===item.id}]" @click="navigate(item.id)"><component :is="item.icon" :size="19"/><span>{{item.label}}</span><span v-if="item.id==='sales'&&cartQuantity" class="tiny-counter">{{cartQuantity}}</span></button></nav>
    <div class="sidebar-bottom"><div class="support-box"><Boxes :size="20"/><strong>Todo bajo control</strong><p>Productos, ventas e inventario en un solo lugar.</p></div><button class="reset-btn" @click="restoreDemo"><RotateCcw :size="15"/> Restablecer demostración</button></div>
  </aside>
  <div v-if="mobileMenu" class="mobile-shade" @click="mobileMenu=false"></div>
  <main class="workspace">
    <header class="topbar"><div class="mobile-top"><button class="icon-btn menu-toggle" @click="mobileMenu=!mobileMenu"><Menu :size="22"/></button><div class="breadcrumb">FERRECONTROL <span>/</span> {{menu.find(x=>x.id===page)?.label}}</div></div><div class="user-pill"><div class="user-avatar">JD</div><div><strong>Jorge Daniel</strong><small>Administrador</small></div></div></header>
    <div class="content">
      <template v-if="page==='dashboard'">
        <div class="page-heading"><div><div class="eyebrow">PANEL GENERAL</div><h1>Resumen del negocio</h1><p>Información actualizada de tu ferretería.</p></div><button class="btn primary" @click="openForm()"><Plus :size="18"/> Nuevo producto</button></div>
        <div class="stats"><StatCard label="Productos registrados" :value="productCount" subtitle="Referencias en catálogo" type="products"/><StatCard label="Unidades disponibles" :value="stockTotal" subtitle="Existencias en almacén" type="sales"/><StatCard label="Ventas acumuladas" :value="money(totalRevenue)" subtitle="Ingresos registrados" type="revenue"/><StatCard label="Stock bajo" :value="alerts.length" subtitle="Productos que requieren atención" type="alert"/></div>
        <div class="grid-two"><section class="panel"><div class="panel-heading"><div><h2>Estado del inventario</h2><p>Resumen por categoría</p></div><Package :size="19" class="muted"/></div><div class="category-bars"><div v-for="cat in categories" :key="cat" class="category-row"><div class="category-info"><span>{{cat}}</span><strong>{{data.products.filter(p=>p.category===cat).length}} productos</strong></div><div class="bar-track"><div class="bar-fill" :style="{width:`${productCount?data.products.filter(p=>p.category===cat).length/productCount*100:0}%`}"></div></div></div></div></section>
        <section class="panel"><div class="panel-heading"><div><h2>Alertas de inventario</h2><p>Productos para reabastecer</p></div><CircleAlert :size="20" class="orange"/></div><div v-if="alerts.length" class="alerts"><div v-for="p in alerts.slice(0,5)" :key="p.id" class="alert-item"><div class="alert-symbol"><CircleAlert :size="18"/></div><div class="alert-name"><strong>{{p.name}}</strong><small>{{p.sku}}</small></div><span class="stock-badge low">{{p.stock}} unidades</span></div></div><div v-else class="empty compact"><Check :size="32"/><strong>¡Todo en orden!</strong><p>No hay productos con existencias bajas.</p></div><button class="text-action" @click="navigate('products')">Ver inventario <ArrowUpRight :size="16"/></button></section></div>
        <section class="panel recent-panel"><div class="panel-heading"><div><h2>Últimas ventas</h2><p>Actividad reciente del negocio</p></div><button class="text-action" @click="navigate('history')">Ver historial <ArrowUpRight :size="16"/></button></div><div v-if="data.sales.length" class="table-wrap"><table><thead><tr><th>Código</th><th>Fecha</th><th>Artículos</th><th>Total</th></tr></thead><tbody><tr v-for="s in data.sales.slice(0,5)" :key="s.id"><td class="mono">{{s.id}}</td><td>{{dateTime(s.date)}}</td><td>{{s.items.reduce((n,i)=>n+i.quantity,0)}} unidades</td><td class="strong">{{money(s.total)}}</td></tr></tbody></table></div><div v-else class="empty compact"><ReceiptText :size="29"/><strong>Aún no hay ventas</strong><p>Realiza tu primera venta para ver el movimiento aquí.</p><button class="btn subtle" @click="navigate('sales')">Ir a ventas</button></div></section>
      </template>
      <template v-if="page==='products'"><div class="page-heading"><div><div class="eyebrow">CATÁLOGO</div><h1>Gestión de productos</h1><p>Administra artículos, precios y existencias.</p></div><button class="btn primary" @click="openForm()"><Plus :size="18"/> Agregar producto</button></div><section class="panel"><div class="toolbar"><div class="search-box"><Search :size="18"/><input v-model="search" placeholder="Buscar nombre o código SKU..."/></div><select v-model="category" class="filter-select"><option>Todas</option><option v-for="cat in categories" :key="cat">{{cat}}</option></select><span class="result-count">{{filtered.length}} resultados</span></div><div class="table-wrap"><table><thead><tr><th>PRODUCTO</th><th>CATEGORÍA</th><th>PRECIO</th><th>EXISTENCIAS</th><th>ACCIONES</th></tr></thead><tbody><tr v-for="p in filtered" :key="p.id"><td><div class="product-name"><span class="product-icon"><Wrench :size="18"/></span><div><strong>{{p.name}}</strong><small>{{p.sku}}</small></div></div></td><td><span class="category-chip">{{p.category}}</span></td><td class="strong">{{money(p.price)}}</td><td><span class="stock-badge" :class="p.stock<=p.minStock?'low':'good'">{{p.stock<=p.minStock?'● Bajo · ':'● '}}{{p.stock}} uds.</span></td><td><div class="action-buttons"><button class="icon-btn" title="Editar" @click="openForm(p)"><Pencil :size="17"/></button><button class="icon-btn danger" title="Eliminar" @click="removeProduct(p)"><Trash2 :size="17"/></button></div></td></tr></tbody></table></div><div v-if="!filtered.length" class="empty"><Search :size="33"/><strong>No se encontraron productos</strong><p>Prueba con otro término de búsqueda.</p></div></section></template>
      <template v-if="page==='sales'"><div class="page-heading"><div><div class="eyebrow">PUNTO DE VENTA</div><h1>Registrar nueva venta</h1><p>Selecciona los productos y confirma la compra.</p></div><div class="counter-pill"><ShoppingCart :size="17"/> {{cartQuantity}} artículos</div></div><div class="sales-layout"><section class="panel"><div class="panel-heading"><div><h2>Seleccionar productos</h2><p>Agrega productos disponibles al carrito</p></div></div><div class="search-box sales-search"><Search :size="18"/><input v-model="search" placeholder="Buscar producto..."/></div><div class="sales-products"><div v-for="p in data.products.filter(x=>x.name.toLowerCase().includes(search.toLowerCase())||x.sku.toLowerCase().includes(search.toLowerCase()))" :key="p.id" class="sale-product"><div class="product-icon"><Wrench :size="19"/></div><div class="sale-item-details"><strong>{{p.name}}</strong><small>{{money(p.price)}} · Disponibles: {{availableToAdd(p)}}</small></div><button class="btn small" :disabled="availableToAdd(p)<=0" @click="addCart(p)"><Plus :size="16"/> Agregar</button></div></div></section><section class="panel checkout"><div class="panel-heading"><div><h2>Resumen de compra</h2><p>{{cartQuantity}} artículos seleccionados</p></div><ShoppingCart :size="20" class="muted"/></div><div v-if="!cart.length" class="empty cart-empty"><ShoppingCart :size="42"/><strong>Tu carrito está vacío</strong><p>Agrega productos para empezar una venta.</p></div><div v-else class="cart-lines"><div class="cart-line" v-for="line in cart" :key="line.id"><div class="cart-name"><strong>{{line.name}}</strong><small>{{money(line.price)}} c/u</small></div><div class="qty-control"><button @click="adjust(line.id,-1)"><Minus :size="13"/></button><span>{{line.quantity}}</span><button @click="adjust(line.id,1)"><Plus :size="13"/></button></div><strong>{{money(line.price*line.quantity)}}</strong></div></div><div class="checkout-bottom"><div class="total-row"><span>Total a pagar</span><strong>{{money(cartTotal)}}</strong></div><button class="btn primary wide" :disabled="!cart.length" @click="checkout"><Check :size="19"/> Confirmar venta</button><p>Al confirmar, el inventario se actualiza automáticamente.</p></div></section></div></template>
      <template v-if="page==='history'"><div class="page-heading"><div><div class="eyebrow">REGISTROS</div><h1>Historial de ventas</h1><p>Consulta los movimientos realizados en el sistema.</p></div><button class="btn subtle" :disabled="!data.sales.length" @click="exportCsv"><Download :size="18"/> Exportar CSV</button></div><div class="stats history-stats"><StatCard label="Total de ventas" :value="data.sales.length" subtitle="Transacciones registradas" type="sales"/><StatCard label="Ingresos totales" :value="money(totalRevenue)" subtitle="Ventas acumuladas" type="revenue"/></div><section class="panel"><div class="panel-heading"><div><h2>Transacciones registradas</h2><p>Detalle de ventas realizadas</p></div></div><div v-if="data.sales.length" class="table-wrap"><table><thead><tr><th>CÓDIGO</th><th>FECHA</th><th>PRODUCTOS</th><th>UNIDADES</th><th>TOTAL</th></tr></thead><tbody><tr v-for="s in data.sales" :key="s.id"><td class="mono">{{s.id}}</td><td>{{dateTime(s.date)}}</td><td><div class="sales-detail" v-for="line in s.items" :key="line.id">{{line.name}} × {{line.quantity}}</div></td><td>{{s.items.reduce((n,i)=>n+i.quantity,0)}}</td><td class="strong">{{money(s.total)}}</td></tr></tbody></table></div><div v-else class="empty"><ReceiptText :size="40"/><strong>Todavía no hay ventas</strong><p>Ve al módulo de ventas para registrar tu primera transacción.</p><button class="btn primary" @click="navigate('sales')">Nueva venta</button></div></section></template>
    </div>
    <footer>FerreControl · Sistema de gestión comercial · Proyecto académico</footer>
  </main>
  <ProductForm v-if="formOpen" :product="editing" :categories="categories" @close="formOpen=false" @save="saveProduct"/>
  <Transition name="toast"><div v-if="notice" class="toast"><Check :size="17"/> {{notice}}</div></Transition>
</div>
</template>
